import { TaskManager } from './src/task-manager.ts';

const tm = new TaskManager();

// Create a task with all fields populated
const task = tm.createTask({ 
  title: "Original Task", 
  priority: 3, 
  description: "Original description",
  status: "in_progress",
  dueDate: "2024-12-31"
});

console.log("Original task:", JSON.stringify(task, null, 2));

// Update only the title - other fields should remain unchanged
const updated = tm.updateTask(task.id, { title: "Updated Title" });

console.log("\nUpdated task (only title changed):", JSON.stringify(updated, null, 2));

// Check if other fields were preserved
let bugFound = false;

if (updated.description !== "Original description") {
  console.log("\n❌ BUG: description was erased:", updated.description);
  bugFound = true;
}

if (updated.priority !== 3) {
  console.log("\n❌ BUG: priority was erased:", updated.priority);
  bugFound = true;
}

if (updated.status !== "in_progress") {
  console.log("\n❌ BUG: status was erased:", updated.status);
  bugFound = true;
}

if (updated.dueDate !== "2024-12-31") {
  console.log("\n❌ BUG: dueDate was erased:", updated.dueDate);
  bugFound = true;
}

if (!bugFound) {
  console.log("\n✅ All fields preserved correctly!");
} else {
  console.log("\n⚠️  Bug confirmed: fields not in update were erased");
  process.exit(1);
}

